package deskhouse;
 public final class DeskCapacity {
     public static int freeDeskCount(int total, int maintenance, int reserved) {
         return Math.max(0, total - maintenance - reserved);
     }
     public static int reservableDeskCount(int total, int maintenance) {
         return Math.max(0, total - maintenance);
     }
 }

