package deskhouse;
 import org.junit.jupiter.api.Test;
 import static org.junit.jupiter.api.Assertions.assertEquals;
 class DeskCapacityTest {
     @Test void reservationsExceedOpenDesks() {
         assertEquals(0, DeskCapacity.freeDeskCount(18, 5, 16));
     }
     @Test void maintenanceReducesReservableDesks() {
         assertEquals(13, DeskCapacity.reservableDeskCount(18, 5));
     }
 }
